function translateNode(node, lang) {
    if (node.nodeType === 3) { // Text node
        let text = node.nodeValue.trim();
        if (text === '') return;
        
        if (!node.originalText) {
            node.originalText = text;
        }
        
        let targetText = node.originalText;
        if (lang === 'en' && deepDict[targetText]) {
            node.nodeValue = node.nodeValue.replace(targetText, deepDict[targetText]);
        } else if (lang === 'tr') {
            node.nodeValue = node.nodeValue.replace(text, node.originalText);
        }
    } else if (node.nodeType === 1) { // Element node
        if (node.tagName === 'SCRIPT' || node.tagName === 'STYLE') return;
        if (node.placeholder) {
            if (!node.originalPlaceholder) node.originalPlaceholder = node.placeholder;
            let targetPlaceholder = node.originalPlaceholder;
            if (lang === 'en' && deepDict[targetPlaceholder]) {
                node.placeholder = deepDict[targetPlaceholder];
            } else if (lang === 'tr') {
                node.placeholder = node.originalPlaceholder;
            }
        }
        node.childNodes.forEach(child => translateNode(child, lang));
    }
}

function applyLanguage(lang) {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (translations[lang] && translations[lang][key]) {
            el.textContent = translations[lang][key];
        }
    });
    
    translateNode(document.body, lang);
}

document.addEventListener("DOMContentLoaded", () => {
    let currentLang = localStorage.getItem('atys_lang') || 'tr';
    
    // First pass: synchronous to prevent flash
    applyLanguage(currentLang);
    const langSelect = document.getElementById('langSelect');
    if (langSelect) {
        langSelect.value = currentLang;
    }
    
    // Second pass: defer slightly to catch dynamically injected texts (e.g. 'Yönetici')
    setTimeout(() => {
        applyLanguage(currentLang);
    }, 100);

    // Global User UI Sync
    const userStr = localStorage.getItem('atys_user');
    if (userStr) {
        const user = JSON.parse(userStr);
        const displayName = user.first_name ? (user.first_name + ' ' + (user.last_name || '')).trim() : user.username;
        const roleName = user.role === 'admin' ? 'Yönetici' : 'Çiftçi';
        
        document.querySelectorAll('.name').forEach(el => el.textContent = displayName);
        document.querySelectorAll('.role').forEach(el => el.textContent = roleName);
        const welcomeEl = document.getElementById('welcomeName');
        if (welcomeEl) welcomeEl.textContent = user.first_name || user.username;

        if (user.avatar_url) {
            const ts = '?t=' + new Date().getTime();
            document.querySelectorAll('.sidebar-avatar-img, .header-avatar').forEach(img => {
                img.src = user.avatar_url + ts;
            });
        }
    }
});

window.changeLanguage = function(lang) {
    localStorage.setItem('atys_lang', lang);
    applyLanguage(lang);
}

